import json,pathlib,html,csv,hashlib,argparse
parser=argparse.ArgumentParser(description='Generate the asset gallery for one prototype version.')
parser.add_argument('level_directory',type=pathlib.Path)
R=parser.parse_args().level_directory.resolve();P=R/'assets'
if not (P/'layers/manifest.json').is_file():parser.error(f'Missing compiled layer manifest: {P / "layers/manifest.json"}')
m=json.loads((P/'layers/manifest.json').read_text(encoding='utf-8'))
rows=[{'layer':x['id'],'source_role':x['source'],'generated_plate':x['plate'],'x':x['x'],'y':x['y'],'width':x['width'],'height':x['height'],'artwork':'layers/'+x['id']+'.png','mask':'layers/'+x['id']+'.mask.png','coverage_samples':len(x['cells']),'sha256':hashlib.sha256((P/'layers'/f"{x['id']}.png").read_bytes()).hexdigest()} for x in m]
with (P/'layer-map.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)
cards=''.join('<article data-filter="'+html.escape(x['layer']+' '+x['source_role']+' '+x['generated_plate'],quote=True)+'"><a href="'+x['artwork']+'"><img loading="lazy" src="'+x['artwork']+'"></a><h3>'+x['layer']+'</h3><p>'+html.escape(x['source_role'])+'</p><small>'+x['generated_plate']+' · '+str(x['width'])+' × '+str(x['height'])+' · position '+str(x['x'])+', '+str(x['y'])+'</small><p><a href="'+x['artwork']+'">PNG layer</a> · <a href="'+x['mask']+'">Alpha mask</a></p></article>' for x in rows)
plates=''.join('<figure><a href="plates/'+p.name+'"><img loading="lazy" src="plates/'+p.name+'"></a><figcaption>'+p.stem+'</figcaption></figure>' for p in sorted((P/'plates').glob('*.png')))
(P/'gallery.html').write_text('''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Camellia Studio — Layer Workshop</title><style>body{margin:30px;background:#21182e;color:#f4eafa;font:15px system-ui}a{color:#c2f3e8}h1{font-size:36px}p,small{color:#c3b4d0}input{padding:12px;width:90%;background:#3e2b51;border:1px solid #8c69a7;color:white;border-radius:8px;margin:15px 0}section{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:16px}article,figure{margin:0;background:#342544;padding:12px;border-radius:12px}article img{width:100%;height:200px;object-fit:contain;background:repeating-conic-gradient(#a99caf 0% 25%,#ded4e7 0% 50%) 50%/20px 20px}figure img{width:100%;height:300px;object-fit:contain}h3{font-size:14px}small{font-size:10px}.pair{display:flex;gap:18px;max-width:720px}.pair img{width:50%;border-radius:12px}[hidden]{display:none!important}</style><h1>Camellia Studio / Layer Workshop</h1><p>'''+str(len(rows))+''' active raster sprites + '''+str(len(rows))+''' alpha masks. </p><p><a href="../index.html">Play the makeover</a> · <a href="layer-map.csv">Layer mapping CSV</a> · <a href="../authoring/prompts.json">All generation prompts</a> · <a href="PROVENANCE.md">Provenance & build notes</a></p><h2>Registered source plates</h2><section>'''+plates+'''</section><h2>Independent sprite layers</h2><p>Checkerboard shows transparency. Each PNG retains its original registration through the x/y values in the manifest. Masks contain no visible artwork.</p><input id="filter" placeholder="Filter by layer, source role or plate"><section>'''+cards+'''</section><script>document.getElementById('filter').oninput=e=>document.querySelectorAll('article').forEach(a=>a.hidden=!a.dataset.filter.toLowerCase().includes(e.target.value.toLowerCase()))</script>''',encoding='utf-8')
print(f'Gallery and CSV: {len(rows)} artwork layers, all with independent masks.')
